"use client";

import { useId, useState } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";

import { formatDay, formatOnePlace, formatWhole, sampleDate } from "../lib/format";
import {
  JOURNEY_STEPS,
  type JourneyChannel,
  journeyCounts,
  type JourneyStep,
  stepCount,
} from "../lib/journey-flow-layout";
import { ROLL_ONE_PLACE, ROLL_WHOLE } from "../lib/roll-formats";
import { BlockFrame } from "../parts/block-frame";
import { FlowDiagram } from "./journey-flow/flow-diagram";
import { DROP_NAMES } from "./journey-flow/names";

const CHANNELS: { value: JourneyChannel; label: string; phrase: string }[] = [
  { value: "all", label: "All", phrase: "from any channel" },
  { value: "search", label: "Search", phrase: "from search" },
  { value: "ads", label: "Ads", phrase: "from ads" },
  { value: "referral", label: "Referral", phrase: "from a referral" },
];

const percentOf = (part: number, whole: number) => (whole === 0 ? 0 : (part / whole) * 100);

/**
 * The booking journey as a flow: three channels merge into the people who
 * visited, then at each stage the people who stay and the people who leave
 * split apart. Pointing at a channel or a step traces its people through the
 * whole journey; picking a channel also sets the headline figures.
 */
export function JourneyFlow({ className }: { className?: string }) {
  const [channel, setChannel] = useState<JourneyChannel>("all");
  const [selected, setSelected] = useState<JourneyStep | null>(null);
  const titleId = useId();

  const counts = journeyCounts(channel);
  const visited = counts[0] ?? 0;
  const attended = counts[counts.length - 1] ?? 0;
  const phrase = CHANNELS.find((item) => item.value === channel)?.phrase ?? "";

  // The largest drop is measured across every channel, like the drawing.
  const totals = journeyCounts("all");
  const largest = JOURNEY_STEPS.filter((step) => step.kind === "drop")
    .map((step) => ({ name: DROP_NAMES[step.stage] ?? "", count: stepCount(step, totals) }))
    .sort((a, b) => b.count - a.count)[0];

  const figures = [
    { label: "Visited", value: visited, format: ROLL_WHOLE, suffix: "" },
    { label: "Attended", value: attended, format: ROLL_WHOLE, suffix: "" },
    { label: "Attendance rate", value: percentOf(attended, visited), format: ROLL_ONE_PLACE, suffix: "%" },
  ];

  const lowerFirst = (text: string) => text.charAt(0).toLowerCase() + text.slice(1);
  const sentence = largest ? `The biggest drop is at ${lowerFirst(largest.name)}.` : "";
  const summary = `Of ${formatWhole(visited)} people who visited the booking page ${phrase}, ${formatWhole(attended)} attended, ${formatOnePlace(percentOf(attended, visited))}%.`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Booking journey
          </h2>
          <p className="text-sm text-muted-foreground">
            {formatDay(sampleDate(29))} to {formatDay(sampleDate(0))}
          </p>
        </div>
        <SegmentedControl
          aria-label="Channel"
          options={CHANNELS}
          value={channel}
          onValueChange={(next) => {
            setSelected(null);
            setChannel(next);
          }}
        />
      </header>

      <dl className="grid grid-cols-3 gap-px border-b border-border bg-border">
        {figures.map((figure) => (
          <div key={figure.label} className="flex min-w-0 flex-col-reverse justify-end gap-1 bg-card px-3 py-4 @md:px-5">
            <dd className="text-xl font-semibold tracking-tight tabular-nums @2xl:text-2xl">
              <NumberTicker value={figure.value} format={figure.format} />
              {figure.suffix}
            </dd>
            <dt className="truncate text-sm text-muted-foreground">{figure.label}</dt>
          </div>
        ))}
      </dl>

      <div className="min-w-0 p-3 @md:p-5">
        <FlowDiagram
          label="Booking journey by channel"
          channel={channel}
          onChannelChange={setChannel}
          selected={selected}
          onSelectedChange={setSelected}
          sentence={sentence}
          summary={summary}
        />
      </div>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

/**
 * Data and layout maths for the journey flow block. Three channels merge into
 * the people who visited. At every stage after that the people who stay rise
 * and the people who leave fall away. Inside a stage, people are counted from
 * the top by how far they get, so a group keeps one band through every stage
 * it passes and a trace is one range cut out of each part.
 */

/** Where the visitors of the booking page came from. */
export type JourneyChannel = "all" | "search" | "ads" | "referral";

/** One channel that feeds the journey. */
export type JourneySource = Exclude<JourneyChannel, "all">;

/** One stage of the booking journey. */
export interface JourneyStage {
  /** The full name, used in sentences. */
  label: string;
  /** The name shown beside the stage's bar. */
  short: string;
  /** What happened to the people who did not reach this stage. Empty for the first stage. */
  lost: string;
}

/** The five stages, in order. */
export const JOURNEY_STAGES: JourneyStage[] = [
  { label: "Visited the booking page", short: "Visited", lost: "" },
  { label: "Picked a time", short: "Picked a time", lost: "Left before picking a time" },
  { label: "Gave details", short: "Gave details", lost: "Left at the details form" },
  { label: "Confirmed", short: "Confirmed", lost: "Did not confirm" },
  { label: "Attended", short: "Attended", lost: "Did not attend" },
];

// People who reached each stage in the last 30 days, by channel. Each row only falls.
const CHANNEL_COUNTS = {
  search: [4200, 2814, 2226, 1974, 1722],
  ads: [2600, 1326, 936, 780, 624],
  referral: [1200, 936, 804, 744, 684],
} satisfies Record<JourneySource, number[]>;

/** The channels, in the order they stack from the top. */
export const JOURNEY_SOURCES: JourneySource[] = ["search", "ads", "referral"];

/** The people who reached each stage for one channel. "All" adds the three channels up. */
export function journeyCounts(channel: JourneyChannel): number[] {
  if (channel !== "all") return CHANNEL_COUNTS[channel];
  return JOURNEY_STAGES.map((_, stage) =>
    JOURNEY_SOURCES.reduce((total, source) => total + (CHANNEL_COUNTS[source][stage] ?? 0), 0),
  );
}

/** A step of the journey: the people who reached a stage, or the people who left before it. */
export interface JourneyStep {
  stage: number;
  kind: "main" | "drop";
}

/** One bar of the drawing: a channel, or a step. */
export type JourneyPart = { type: "source"; source: JourneySource } | { type: "step"; step: JourneyStep };

/** A stable key for a part, such as `source-ads`, `main-2` or `drop-3`. */
export const partKey = (part: JourneyPart) =>
  part.type === "source" ? `source-${part.source}` : `${part.step.kind}-${part.step.stage}`;

/** Every step, stage by stage. The first stage has no drop step. */
export const JOURNEY_STEPS: JourneyStep[] = JOURNEY_STAGES.flatMap((_, stage): JourneyStep[] =>
  stage === 0 ? [{ stage, kind: "main" }] : [{ stage, kind: "main" }, { stage, kind: "drop" }],
);

/** Every bar of the drawing: the channels, then the steps. */
export const JOURNEY_PARTS: JourneyPart[] = [
  ...JOURNEY_SOURCES.map((source): JourneyPart => ({ type: "source", source })),
  ...JOURNEY_STEPS.map((step): JourneyPart => ({ type: "step", step })),
];

/** How many people a step holds. A drop step holds the people the stage before had and this one lacks. */
export function stepCount(step: JourneyStep, counts: number[]): number {
  const here = counts[step.stage] ?? 0;
  return step.kind === "main" ? here : (counts[step.stage - 1] ?? 0) - here;
}

const TOTALS = journeyCounts("all");
const LAST_STAGE = JOURNEY_STAGES.length - 1;

/** The band a step's people occupy, counted in people from the top of any stage. */
function stepRange(step: JourneyStep): [number, number] {
  const here = TOTALS[step.stage] ?? 0;
  return step.kind === "main" ? [0, here] : [here, TOTALS[step.stage - 1] ?? 0];
}

/** How many people a part holds, across every channel. */
export function partPeople(part: JourneyPart): number {
  return part.type === "source" ? (CHANNEL_COUNTS[part.source][0] ?? 0) : stepCount(part.step, TOTALS);
}

// The drawing is a 0 to 100 box. Six columns of bars: the channels, then the five stages.
/** The width of a bar in the box. */
export const NODE_WIDTH = 2.4;
/** The height of everyone who visited. */
const FLOW_HEIGHT = 62;
/** How far the last stage sits above the first, so the people who stay climb. */
const RISE = 19;
const DROP_GAP = 12;
const SOURCE_GAP = 5;
const UNIT = FLOW_HEIGHT / (TOTALS[0] || 1);

/** The left edge of a column of bars. Column 0 holds the channels. */
const columnLeft = (column: number) => (column * (100 - NODE_WIDTH)) / JOURNEY_STAGES.length;

/** The top of the bar of people who reached a stage. */
const stageTop = (stage: number) => RISE * (1 - stage / LAST_STAGE);

/** The people in the channels stacked above a channel. */
function peopleAbove(source: JourneySource): number {
  const index = JOURNEY_SOURCES.indexOf(source);
  return JOURNEY_SOURCES.slice(0, index).reduce((total, other) => total + (CHANNEL_COUNTS[other][0] ?? 0), 0);
}

/** Where a bar sits in the box. */
export interface PartBox {
  left: number;
  top: number;
  height: number;
}

/** The bar of a part. */
export function partBox(part: JourneyPart): PartBox {
  const height = partPeople(part) * UNIT;
  if (part.type === "source") {
    const index = JOURNEY_SOURCES.indexOf(part.source);
    return { left: columnLeft(0), top: RISE + peopleAbove(part.source) * UNIT + index * SOURCE_GAP, height };
  }
  const { stage, kind } = part.step;
  const top = kind === "main" ? stageTop(stage) : stageTop(stage) + (TOTALS[stage] ?? 0) * UNIT + DROP_GAP;
  return { left: columnLeft(stage + 1), top, height };
}

/** A slice of a part: `amount` people, starting `offset` people below the part's top. */
export interface Portion {
  offset: number;
  amount: number;
}

/**
 * The slice of a part that belongs to a traced part. A traced channel lights
 * its own people in every step. A traced step lights its band in every step
 * it passes, and in every channel the people who came from that channel.
 */
export function tracedPortion(part: JourneyPart, traced: JourneyPart | null): Portion {
  const everyone = { offset: 0, amount: partPeople(part) };
  if (!traced) return everyone;
  if (traced.type === "source") {
    if (part.type === "source") return part.source === traced.source ? everyone : { offset: 0, amount: 0 };
    const amount = stepCount(part.step, CHANNEL_COUNTS[traced.source]);
    // In the first stage a channel's people sit where its ribbon arrives.
    const first = part.step.stage === 0 && part.step.kind === "main";
    return { offset: first ? peopleAbove(traced.source) : 0, amount };
  }
  if (part.type === "source") return { offset: 0, amount: stepCount(traced.step, CHANNEL_COUNTS[part.source]) };
  const own = stepRange(part.step);
  const band = stepRange(traced.step);
  const low = Math.max(own[0], band[0]);
  const high = Math.min(own[1], band[1]);
  return high > low ? { offset: low - own[0], amount: high - low } : { offset: 0, amount: 0 };
}

const point = (x: number, y: number) => `${x.toFixed(2)} ${y.toFixed(2)}`;

/** The bar of a part, cut down to a slice. Every bar path has the same commands, so one can morph into another. */
export function barPath(part: JourneyPart, portion: Portion = { offset: 0, amount: partPeople(part) }): string {
  const box = partBox(part);
  const top = box.top + portion.offset * UNIT;
  const bottom = top + portion.amount * UNIT;
  const right = box.left + NODE_WIDTH;
  return `M${point(box.left, top)} L${point(right, top)} L${point(right, bottom)} L${point(box.left, bottom)} Z`;
}

/** Where a part's ribbon starts and ends. The first stage has no ribbon of its own: the channels feed it. */
function ribbonEnds(part: JourneyPart): { fromX: number; fromTop: number; toX: number; toTop: number } | null {
  const box = partBox(part);
  if (part.type === "source") {
    return {
      fromX: box.left + NODE_WIDTH,
      fromTop: box.top,
      toX: columnLeft(1),
      toTop: stageTop(0) + peopleAbove(part.source) * UNIT,
    };
  }
  const { stage } = part.step;
  if (stage === 0) return null;
  return {
    fromX: columnLeft(stage) + NODE_WIDTH,
    fromTop: stageTop(stage - 1) + stepRange(part.step)[0] * UNIT,
    toX: box.left,
    toTop: box.top,
  };
}

/** Whether a part has a ribbon. */
export const hasRibbon = (part: JourneyPart) => ribbonEnds(part) !== null;

/**
 * The ribbon of a part, cut down to a slice. A channel's ribbon carries its
 * people into the first stage; a step's ribbon carries its people in from the
 * stage before.
 */
export function ribbonPath(part: JourneyPart, portion: Portion = { offset: 0, amount: partPeople(part) }): string {
  const ends = ribbonEnds(part);
  if (!ends) return "";
  const shift = portion.offset * UNIT;
  const thickness = portion.amount * UNIT;
  const fromTop = ends.fromTop + shift;
  const toTop = ends.toTop + shift;
  const middle = (ends.fromX + ends.toX) / 2;
  return [
    `M${point(ends.fromX, fromTop)}`,
    `C${point(middle, fromTop)} ${point(middle, toTop)} ${point(ends.toX, toTop)}`,
    `L${point(ends.toX, toTop + thickness)}`,
    `C${point(middle, toTop + thickness)} ${point(middle, fromTop + thickness)} ${point(ends.fromX, fromTop + thickness)}`,
    "Z",
  ].join(" ");
}

/** Where a part sits in the grid the arrow keys walk: column 0 holds the channels, then one column per stage. */
function cellOf(part: JourneyPart) {
  if (part.type === "source") return { column: 0, row: JOURNEY_SOURCES.indexOf(part.source) };
  return { column: part.step.stage + 1, row: part.step.kind === "main" ? 0 : 1 };
}

/** The parts in one column, top to bottom. */
function columnParts(column: number): JourneyPart[] {
  if (column === 0) return JOURNEY_PARTS.filter((part) => part.type === "source");
  return JOURNEY_PARTS.filter((part) => part.type === "step" && part.step.stage === column - 1);
}

/** Where an arrow, Home or End key moves the cursor. Null means the key is not a move. */
export function movePart(key: string, from: JourneyPart): JourneyPart | null {
  const { column, row } = cellOf(from);
  const last = JOURNEY_STAGES.length;
  const pick = (toColumn: number, toRow: number) => {
    const parts = columnParts(Math.min(last, Math.max(0, toColumn)));
    return parts[Math.min(parts.length - 1, Math.max(0, toRow))] ?? from;
  };
  if (key === "ArrowRight") return pick(column + 1, row);
  if (key === "ArrowLeft") return pick(column - 1, row);
  if (key === "ArrowDown") return pick(column, row + 1);
  if (key === "ArrowUp") return pick(column, row - 1);
  if (key === "Home") return pick(0, 0);
  if (key === "End") return pick(last, 0);
  return null;
}

// NumberTicker memoises its formatter on the options object, so every block
// passes one of these constants and never an inline object.

/** A whole number with thousands separators, for a rolling figure. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/** A number with one decimal place, for a rolling figure. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };

/** A dollar amount with no cents, for a rolling figure. */
export const ROLL_MONEY: Intl.NumberFormatOptions = { style: "currency", currency: "USD", maximumFractionDigits: 0 };

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { type KeyboardEvent, useId, useState } from "react";

import { formatOnePlace, formatWhole } from "../../lib/format";
import {
  JOURNEY_PARTS,
  JOURNEY_STAGES,
  type JourneyChannel,
  journeyCounts,
  type JourneyPart,
  type JourneyStep,
  movePart,
  partBox,
  partKey,
  partPeople,
  tracedPortion,
} from "../../lib/journey-flow-layout";
import { FlowLabel, type LabelSide } from "./flow-label";
import { FlowRibbons } from "./flow-ribbons";
import { DROP_LABELS, SOURCE_NAMES } from "./names";
import { partTone } from "./part-tone";

/** Props for the journey diagram. */
export interface FlowDiagramProps {
  /** Names the diagram for screen readers. */
  label: string;
  /** The pinned channel. Its people stay traced after the pointer leaves. */
  channel: JourneyChannel;
  onChannelChange: (channel: JourneyChannel) => void;
  /** The pinned step: its trace stays after the pointer leaves. */
  selected: JourneyStep | null;
  onSelectedChange: (step: JourneyStep | null) => void;
  /** The one short sentence above the drawing. The traced part's sentence replaces it. It keeps one line. */
  sentence: string;
  /** The result in words, for screen readers. */
  summary: string;
}

const TOTALS = journeyCounts("all");
const VISITED = TOTALS[0] ?? 0;
const LAST_STAGE = JOURNEY_STAGES.length - 1;
const FIRST_PART: JourneyPart = { type: "step", step: { stage: 0, kind: "main" } };

const share = (part: number, whole: number) => `${formatOnePlace(whole === 0 ? 0 : (part / whole) * 100)}%`;

const lowerFirst = (text: string) => text.charAt(0).toLowerCase() + text.slice(1);

/** The name written beside a part's bar. */
function partName(part: JourneyPart): string {
  if (part.type === "source") return SOURCE_NAMES[part.source];
  const { stage, kind } = part.step;
  return (kind === "drop" ? DROP_LABELS[stage] : JOURNEY_STAGES[stage]?.short) ?? "";
}

/** What a part's share is measured against: a drop against the stage before, everything else against all visitors. */
function partWhole(part: JourneyPart): number {
  return part.type === "step" && part.step.kind === "drop" ? (TOTALS[part.step.stage - 1] ?? 0) : VISITED;
}

/** Where a part's label sits: channels on the left, stages above their bar, the ends of the flow on the right. */
function labelSide(part: JourneyPart): LabelSide {
  if (part.type === "source") return "before";
  return part.step.kind === "drop" || part.step.stage === LAST_STAGE ? "after" : "above";
}

/** One sentence about a part: its people and their share. */
function describePart(part: JourneyPart): string {
  const count = partPeople(part);
  if (part.type === "source") {
    const attended = journeyCounts(part.source)[LAST_STAGE] ?? 0;
    return `${SOURCE_NAMES[part.source]}: ${formatWhole(count)} visitors, ${share(count, VISITED)} of all visitors. ${formatWhole(attended)} attended.`;
  }
  const stage = JOURNEY_STAGES[part.step.stage];
  if (!stage) return "";
  const before = TOTALS[part.step.stage - 1] ?? 0;
  if (part.step.kind === "drop") {
    const earlier = lowerFirst(JOURNEY_STAGES[part.step.stage - 1]?.label ?? "");
    return `${stage.lost}: ${formatWhole(count)} people, ${share(count, before)} of the ${formatWhole(before)} who ${earlier}.`;
  }
  return `${stage.label}: ${formatWhole(count)} people, ${share(count, VISITED)} of those who visited.`;
}

/**
 * The journey as a flow that merges and then splits. Three channels join into
 * the people who visited; at each stage the people who stay climb and the
 * people who leave fall away, and every bar is named where it sits. The part
 * under the pointer or the keyboard is traced through the whole drawing and
 * the rest dims, and the line above the drawing says its figures. A click, Enter or Space pins the trace; a second one or
 * Escape clears it. It is one tab stop: the arrow keys move between bars.
 */
export function FlowDiagram({
  label,
  channel,
  onChannelChange,
  selected,
  onSelectedChange,
  sentence,
  summary,
}: FlowDiagramProps) {
  const [active, setActive] = useState<JourneyPart | null>(null);
  const baseId = useId();
  const optionId = (part: JourneyPart) => `${baseId}-${partKey(part)}`;

  const pinned: JourneyPart | null = selected
    ? { type: "step", step: selected }
    : channel === "all"
      ? null
      : { type: "source", source: channel };
  const pinnedKey = pinned ? partKey(pinned) : null;
  const activeKey = active ? partKey(active) : null;
  const traced = active ?? pinned;

  const toggle = (part: JourneyPart) => {
    const clear = partKey(part) === pinnedKey;
    if (part.type === "source") {
      onSelectedChange(null);
      onChannelChange(clear ? "all" : part.source);
    } else {
      onSelectedChange(clear ? null : part.step);
    }
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const from = active ?? pinned ?? FIRST_PART;
    const next = movePart(event.key, from);
    if (next) setActive(next);
    else if (event.key === "Enter" || event.key === " ") toggle(from);
    else if (event.key === "Escape" && pinned) toggle(pinned);
    else return;
    event.preventDefault();
  };

  return (
    <div className="flex min-w-0 flex-col gap-3">
      <p className="h-5 truncate text-sm text-muted-foreground">{active ? describePart(active) : sentence}</p>
      <p className="sr-only">{summary}</p>
      <p aria-live="polite" className="sr-only">
        {active ? describePart(active) : ""}
      </p>
      <div
        role="listbox"
        tabIndex={0}
        aria-label={`${label}. Use the arrow keys to trace a channel or a step, Enter to keep the trace, Escape to clear it.`}
        aria-activedescendant={active ? optionId(active) : undefined}
        onKeyDown={onKeyDown}
        onFocus={() => setActive((current) => current ?? pinned ?? FIRST_PART)}
        onBlur={() => setActive(null)}
        className="group overflow-x-auto scroll-fade-effect-x scrollbar-none rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        <div role="presentation" className="relative h-96 min-w-160">
          <div role="presentation" className="absolute inset-y-0 right-28 left-24 mt-10 mb-4">
            <FlowRibbons traced={traced} active={active} onSelect={toggle} onHover={setActive} />
            {JOURNEY_PARTS.map((part) => {
              const key = partKey(part);
              const count = partPeople(part);
              const drop = part.type === "step" && part.step.kind === "drop";
              return (
                <FlowLabel
                  key={key}
                  id={optionId(part)}
                  role="option"
                  aria-selected={key === pinnedKey}
                  aria-label={describePart(part)}
                  data-active={key === activeKey}
                  onClick={() => toggle(part)}
                  onPointerEnter={() => setActive(part)}
                  onPointerLeave={() => setActive(null)}
                  box={partBox(part)}
                  side={labelSide(part)}
                  tone={partTone(part)}
                  name={partName(part)}
                  count={`${drop ? "−" : ""}${formatWhole(count)}`}
                  share={count === VISITED ? "" : share(count, partWhole(part))}
                  dimmed={tracedPortion(part, traced).amount === 0}
                  pinned={key === pinnedKey}
                />
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

import type { HTMLAttributes } from "react";

