/** Where a label sits against its bar. */
export type LabelSide = "before" | "above" | "after";

/** Props for the label of one bar. */
export interface FlowLabelProps extends HTMLAttributes<HTMLDivElement> {
  box: PartBox;
  side: LabelSide;
  tone: PartTone;
  name: string;
  /** The people in the bar, already formatted. */
  count: string;
  /** Their share, already formatted. */
  share: string;
  /** Dims the label while another part is traced. */
  dimmed: boolean;
  /** Marks the label as the pinned trace. */
  pinned: boolean;
}

/**
 * The corner of the drawing a label hangs from, in percent of the plot: `x`
 * measures from the side named in `SIDE_CLASS`, `y` from the top or the bottom.
 */
function anchor(box: PartBox, side: LabelSide) {
  const middle = box.top + box.height / 2;
  if (side === "before") return { x: 100 - box.left, y: middle };
  if (side === "after") return { x: box.left + NODE_WIDTH, y: middle };
  return { x: 100 - box.left - NODE_WIDTH, y: 100 - box.top };
}

const SIDE_CLASS = {
  before: "top-(--y) right-(--x) -translate-y-1/2 pr-1 text-right",
  after: "top-(--y) left-(--x) -translate-y-1/2 pl-1 text-left",
  above: "right-(--x) bottom-(--y) pb-0.5 text-right",
} satisfies Record<LabelSide, string>;

/**
 * The name and figures of one bar, written beside it so the drawing needs no
 * legend. It is also the bar's option in the listbox: it takes the pointer
 * and names the bar for a screen reader.
 */
export function FlowLabel({ box, side, tone, name, count, share, dimmed, pinned, className, ...rest }: FlowLabelProps) {
  const { x, y } = anchor(box, side);
  return (
    <div
      role="presentation"
      className={cn("absolute", SIDE_CLASS[side])}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        { "--x": `${x}%`, "--y": `${y}%` } as VarStyle
      }
    >
      <div
        {...rest}
        className={cn(
          "flex cursor-pointer flex-col rounded-md px-1.5 py-0.5 text-xs leading-4 whitespace-nowrap",
          "motion-safe:transition-opacity motion-safe:duration-150",
          "group-focus-visible:data-[active=true]:ring-2 group-focus-visible:data-[active=true]:ring-ring",
          pinned ? "bg-muted" : undefined,
          dimmed ? "opacity-40" : "opacity-100",
          className,
        )}
      >
        <span className={cn("font-medium", TONE_FILL[tone].name)}>{name}</span>
        <span className="tabular-nums">
          <span className="font-medium text-foreground">{count}</span> <span className="text-muted-foreground">{share}</span>
        </span>
      </div>
    </div>
  );
}

