/** The colour role of a part: one of the channels, the people who stayed, or the people who left. */
export type PartTone = JourneySource | "kept" | "lost";

/** Each channel has its own colour. From the first stage on, people who stay are green and people who leave are orange-red. */
export function partTone(part: JourneyPart): PartTone {
  if (part.type === "source") return part.source;
  return part.step.kind === "main" ? "kept" : "lost";
}

