"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";

import { cn } from "@/lib/utils";

import {
  barPath,
  hasRibbon,
  JOURNEY_PARTS,
  type JourneyPart,
  partKey,
  ribbonPath,
  tracedPortion,
} from "../../lib/journey-flow-layout";
import { partTone, TONE_FILL } from "./part-tone";

/** Props for the drawing of the journey flow. */
export interface FlowRibbonsProps {
  /** The part whose people are traced. Null draws every part at full strength. */
  traced: JourneyPart | null;
  /** The part under the keyboard cursor or the pointer, outlined on the drawing. */
  active: JourneyPart | null;
  onSelect: (part: JourneyPart) => void;
  onHover: (part: JourneyPart | null) => void;
}

// Critically damped: a ribbon settles on its new width with no wobble.
const MORPH: Transition = { type: "spring", stiffness: 260, damping: 32, mass: 1 };
const INSTANT: Transition = { duration: 0 };

/**
 * The bars and ribbons of the journey, drawn in a 0 to 100 box that stretches
 * to its frame. Each part has a faint base and a traced slice on top: with a
 * part traced, the slice shrinks to that part's people and the base stays dim.
 */
export function FlowRibbons({ traced, active, onSelect, onHover }: FlowRibbonsProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : MORPH;
  const activeKey = active ? partKey(active) : null;

  const pointer = (part: JourneyPart) => ({
    className: "cursor-pointer",
    onClick: () => onSelect(part),
    onPointerEnter: () => onHover(part),
    onPointerLeave: () => onHover(null),
  });

  return (
    <svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 size-full overflow-visible">
      {JOURNEY_PARTS.filter(hasRibbon).map((part) => {
        const fill = TONE_FILL[partTone(part)];
        const portion = tracedPortion(part, traced);
        return (
          <g key={partKey(part)} {...pointer(part)}>
            <path d={ribbonPath(part)} className={fill.ribbon} />
            <motion.path
              initial={false}
              animate={{ d: ribbonPath(part, portion), opacity: portion.amount > 0 ? 1 : 0 }}
              transition={transition}
              className={fill.ribbonTraced}
            />
          </g>
        );
      })}
      {JOURNEY_PARTS.map((part) => {
        const key = partKey(part);
        const fill = TONE_FILL[partTone(part)];
        const portion = tracedPortion(part, traced);
        return (
          <g key={key} {...pointer(part)}>
            <path d={barPath(part)} className={fill.bar} />
            <motion.path
              initial={false}
              animate={{ d: barPath(part, portion), opacity: portion.amount > 0 ? 1 : 0 }}
              transition={transition}
              strokeWidth="2"
              vectorEffect="non-scaling-stroke"
              className={cn(fill.barTraced, key === activeKey ? "stroke-foreground" : "stroke-transparent")}
            />
          </g>
        );
      })}
    </svg>
  );
}

